mapper.select:
SELECT p.*, u.username as author_username, u.nickname as author_nickname, u.avatar as author_avatar, c.name as category_name, c.description as category_description FROM posts p LEFT JOIN users u ON p.author_id = u.id LEFT JOIN categories c ON p.category_id = c.id WHERE p.status = 'PUBLISHED'
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.category_id = #{categoryId}
ORDER BY p.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM posts p WHERE p.status = 'PUBLISHED'
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.category_id = #{categoryId}

SELECT COUNT(*) FROM posts p
INNER JOIN post_tags pt ON p.id = pt.post_id
WHERE p.status = 'PUBLISHED' AND pt.tag_id = #{tagId}
